    import random
    import time

    LANGUAGE_WRAPPER = 'Let two sequences be defined by the recurrence relations $u_{k+1} = {a} u_k$ and $v_{k+1} = {b} v_k$ for $k \\ge 1$, with initial values $u_1 = {c_a}$ and $v_1 = {d_b}$. A third sequence, $W_k$, is formed by the sum $W_k = u_k + v_k$. Find the remainder when $W_{n}$ is divided by ${mod}$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
primes = [11, 13, 17, 19, 23]
while True:
    p = rng.choice(primes)
    p_squared = p * p

    r = rng.randint(2, p - 1)
    k = rng.randint(1, p)
    # Ensure b is positive
    s_min = r // p + 1 # This is 1 since r < p
    s = rng.randint(s_min, p)

    c = rng.randint(1, p - 1)
    d = rng.randint(1, p - 1)

    # Choose n large enough to require modular exponentiation
    n = rng.randint(p_squared, 3 * p_squared)

    # These conditions prevent the problem from becoming trivial
    valid = True
    if n % 2 == 0:
        if (c * k - d * s) % p == 0:
            valid = False
        if (c + d) % p == 0:
            valid = False
    else: # n is odd
        if (c * k + d * s) % p == 0:
            valid = False
        if c == d:
            valid = False

    if valid:
        a = k * p + r
        b = s * p - r

        if b <= 0:
            continue

        return {
            "a": a,
            "b": b,
            "c_a": c * a,
            "d_b": d * b,
            "n": n,
            "mod": p_squared
        }

    def verifier(assign):
def is_prime(num):
    if num < 2:
        return False
    i = 2
    while i * i <= num:
        if num % i == 0:
            return False
        i += 1
    return True

a, b, c_a, d_b, n, mod = assign['a'], assign['b'], assign['c_a'], assign['d_b'], assign['n'], assign['mod']

if a <= 0 or b <= 0:
    return False, None # Bases must be positive
if c_a % a != 0 or d_b % b != 0:
    return False, None # Initial values must be consistent with recurrence
c = c_a // a
d = d_b // b

if mod < 4:
    return False, None
p = int(mod**0.5)
if p * p != mod:
    return False, None # Modulus must be a perfect square
if not is_prime(p):
    return False, None # Base of modulus must be prime

# This is the key structural property to be discovered by the solver
if (a + b) % p != 0:
    return False, None

r = a % p
if r == 0:
    return False, None # Degenerate case, r must not be a multiple of p

k = (a - r) // p
s = (b + r) // p

# Verify that the problem instance is not a trivial case
if n % 2 == 0:
    if (c * k - d * s) % p == 0 or (c + d) % p == 0:
        return False, None
else:
    if (c * k + d * s) % p == 0 or c == d:
        return False, None

# All checks passed, calculate the solution using the binomial expansion method
p_squared = mod
phi_p_squared = p_squared - p
phi_p = p - 1

# Term 1: C1 * r^n (mod p^2)
exp_r_n = n % phi_p_squared
if exp_r_n == 0: exp_r_n = phi_p_squared
r_n = pow(r, exp_r_n, p_squared)

c1 = (c + d) if n % 2 == 0 else (c - d)
term1 = (c1 * r_n) % p_squared

# Term 2: C2 * n * p * r^(n-1) (mod p^2)
# This is equivalent to p * [C2 * n * r^(n-1) (mod p)]
if n == 1:
    exp_r_n_minus_1 = 0
else:
    exp_r_n_minus_1 = (n - 1) % phi_p
    if exp_r_n_minus_1 == 0: exp_r_n_minus_1 = phi_p

r_n_minus_1_mod_p = pow(r, exp_r_n_minus_1, p)
n_mod_p = n % p

c2_mod_p = ((c * k - d * s) % p) if n % 2 == 0 else ((c * k + d * s) % p)

y_mod_p = (n_mod_p * r_n_minus_1_mod_p * c2_mod_p) % p
term2 = (p * y_mod_p) % p_squared

answer = (term1 + term2) % p_squared
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
